const alertItem = $('Webhook Trigger').first()?.json?.body || {
  status: 'firing',
  severity: 'critical',
  service_name: 'mock-transaction-service',
  error_signature: 'HTTP 500 rate > 5%',
  timestamp: new Date().toISOString()
};

const rawLogsData = $('Fetch Application Logs').first()?.json?.logs || [];
let formattedLogs = '';
if (Array.isArray(rawLogsData) && rawLogsData.length > 0) {
  formattedLogs = rawLogsData.map(log => {
    const header = `[${log.timestamp || 'N/A'}] [${log.level || 'ERROR'}] [corr:${log.correlation_id || 'none'}] fn:${log.function || 'process_transaction'}: ${log.message || ''}`;
    const trace = log.stack_trace ? `\nStack Trace:\n${Array.isArray(log.stack_trace) ? log.stack_trace.join('') : log.stack_trace}` : '';
    return header + trace;
  }).join('\n\n---\n\n');
} else {
  formattedLogs = `[${new Date().toISOString()}] [ERROR] [corr:corr-auto-1] fn:process_transaction: Catastrophic transaction failure\nStack Trace:\nNullPointerException: Object reference not set to an instance of an object at LedgerAccountManager.validate_balance(account_id=None). Line 142 in mock-microservice/main.py`;
}

const commitData = $('Fetch Latest Git Commit').first()?.json;
const commitSha = (Array.isArray(commitData) ? commitData[0]?.sha : commitData?.sha) || 'a7b3c99e4f12d8a5c3e6201b19f04128a3910c4f';
const commitMessage = (Array.isArray(commitData) ? commitData[0]?.commit?.message : commitData?.commit?.message) || 'feat(ledger): optimize batch processing partition logic and null checks';

const rawDiffData = $('Fetch Git Raw Diff').first()?.json;
let rawDiff = '';
if (typeof rawDiffData === 'string' && rawDiffData.trim().length > 0) {
  rawDiff = rawDiffData;
} else if (rawDiffData && rawDiffData.data) {
  rawDiff = String(rawDiffData.data);
} else {
  rawDiff = `diff --git a/mock-microservice/main.py b/mock-microservice/main.py\nindex 8f2a1b..4c9d3e 100644\n--- a/mock-microservice/main.py\n+++ b/mock-microservice/main.py\n@@ -138,5 +138,7 @@ async def process_transaction(request: Request):\n-    if account_id is not None and len(account_id) > 0:\n-        account = get_account(account_id)\n-        balance = account.balance\n+    # Unvalidated direct call introducing unhandled NullPointerException\n+    account = get_account(None)\n+    balance = account.validate_balance(account_id=None)\n+    chunks = batch_partitions[25]`;
}

return [{
  json: {
    alert: alertItem,
    service_name: alertItem.service_name || 'mock-transaction-service',
    error_signature: alertItem.error_signature || 'HTTP 500 rate > 5%',
    commit_sha: commitSha,
    commit_message: commitMessage,
    forensic_logs: formattedLogs,
    raw_git_diff: rawDiff,
    ingestion_timestamp: new Date().toISOString()
  }
}];

