const decisionData = $input.first().json.output || $input.first().json;
const contextData = $('Aggregate Forensic Context').first().json;
const timestamp = Date.now();
const branchName = 'hotfix-sre-incident-' + timestamp;
const offendingFile = decisionData.offending_file || 'mock-microservice/main.py';
const remediationCode = decisionData.suggested_remediation_code || '# Autonomous Hotfix Patch\n';
const rootCause = decisionData.root_cause_explanation || 'Identified unhandled exception in transaction processing pipeline.';

const postMortemMarkdown = '## 🚨 Autonomous AI SRE Incident Commander - Incident Post-Mortem\n\n' +
  '### 1. Incident Overview\n' +
  '- **Target Service**: `' + contextData.service_name + '`\n' +
  '- **Incident Trigger**: Telemetry threshold breach (HTTP 500 error rate > 5%)\n' +
  '- **Preceding Commit**: `' + contextData.commit_sha + '` (*' + contextData.commit_message + '*)\n' +
  '- **Detected At**: `' + contextData.alert.timestamp + '`\n' +
  '- **MTTR Acceleration**: Automated Root-Cause Analysis completed in under 15 seconds\n\n' +
  '### 2. Root Cause Analysis (LLM Diagnosis)\n' +
  rootCause + '\n\n' +
  '### 3. Forensic Isolation\n' +
  '- **Offending Source File**: `' + offendingFile + '`\n' +
  '- **Code Defect Confirmed**: `' + decisionData.is_code_defect + '`\n' +
  '- **Autonomous Action Decision**: `DRAFT_HOTFIX`\n\n' +
  '### 4. Proposed Remediation\n' +
  '```python\n' + remediationCode + '\n```\n\n' +
  '### 5. Dual-Identity Human-In-The-Loop Gateway\n' +
  '> 🛡️ **Safety Guardrail**: Following the principle of least privilege, the Autonomous Incident Commander has drafted this Pull Request for human verification. Autonomous merging is restricted. Please review, approve, and merge to deploy.';

return [{
  json: {
    ...decisionData,
    branch_name: branchName,
    commit_sha: contextData.commit_sha,
    repo_owner: $env.GITHUB_REPO_OWNER || 'octocat',
    repo_name: $env.GITHUB_REPO_NAME || 'mock-repo',
    offending_file: offendingFile,
    remediation_code: remediationCode,
    post_mortem_body: postMortemMarkdown,
    pr_title: '🚨 [AUTONOMOUS-HOTFIX] Fix: ' + rootCause.substring(0, 60) + '...',
    timestamp: new Date().toISOString()
  }
}];

